opencat.script:
    /* ════════════════════════════════════════════════════════════════════
       Single-XML port of the three先行 act files (vfx-heygen-act{A,B,C}.xml).
       The act scripts are kept verbatim except:
         (a) time is localised to each scene: act → scene local seconds
             (ctx.currentTime, the authoritative per-scene clock), and
         (b) every id is prefixed (r1-/r2-/r3-/r4-/r5-/c3-/c4-) so no id
             collides across scenes. One  block covers all fonts.
       All beat values stay 1:1 with the reference source constants; the
       scene-local offsets are pure arithmetic from the reference's own
       window table (HEYGEN_START 5.58, CHROMATIC_START 7.92,
       RGB_ROTATE_START 9.325, RGB_EXIT_START 10.45, PORTAL_START 11.44,
       index.html:1249-1259), never a measured fit.
       ════════════════════════════════════════════════════════════════════ */

    /* ── active-scene guard ─────────────────────────────────────────────
       The single script runs once per frame for the whole film, so each
       act block must test that its own scene window owns the current
       frame. Windows are the region table (ref frames), i.e. pure
       arithmetic on the reference's own cut points, never a measured
       fit. ctx.time is the composition clock; ctx.currentTime is the
       scene-local clock used by every beat below. */
    var ACTIVE = [[0, 5.8], [6.033333333, 11.03333333], [11.26666667, 14.56666667], [14.73333333, 16.63333333], [16.8, 26.26666667]];
    /* CK is shared by every scene block (all four use getSubTree().makeShader
       with CK.TileMode.Clamp); declaring it once at the top keeps the per-scene
       re-timing independent of the block that happens to declare it. */
    var CK = ctx.CanvasKit;
    function inWindow(i) {
      var w = ACTIVE[i];
      return ctx.time >= w[0] - 1e-6 && ctx.time < w[1];
    }
    /* ── Scene r1: VFX sub-composition (local == reference local, offset 0)
       Only the frames this scene owns evaluate it. */
    if (inWindow(0)) {
    /* ── 1:1 port of compositions/vfx-text-cursor.html timeline ────────── */
    var T = ctx.timeline();

    function clamp01(v) { return v < 0 ? 0 : (v > 1 ? 1 : v); }
    function entryEase(t) { return -0.806 * t * t + 1.806 * t; }

    /* ---- V1 ray-march sting (effect lambda, 1:1 source port) ----
       vfx-text-cursor.html:449-546 is a 112-sample screen-space ray-march from
       the cursor toward the wordmark; `acc` accumulates the logo mask and the
       colour is composed from the source primitives:
         hash(p)     = fract(sin(dot(p,[489,589,58]))*492)*2-1
         spectrum(x) = cos((x - vec3(0,0.5,1)) * vec3(0.6,1,0.5) * PI)
       The source renders into a GL canvas whose y is bottom-up; opencat's uv.y
       is top-down, so the field maths is done in GL space (gy = 1 - uv.y/h)
       while the mask/colour image sample is flipped back (1-ly) for the
       top-down texture. Both mask textures are the source `.stage-logo`
       artwork rasterised (#logo-field, full 1920×1080) and sampled as a
       subtree shader child — never retyped. */
    var STING = (uv, image, colormask, u) => {
      const gx = uv.x / u.w;
      const gy = 1.0 - uv.y / u.h;
      const scale = u.scale;
      const lx = (gx - 0.5) / scale + 0.5;
      const ly = (gy - 0.5) / scale + 0.5 + u.logoY / u.h;
      /* mask = the mask canvas coverage. The source `drawLogoMasks` paints
         every `.stage-logo path` with maskCtx.fillStyle="#fff", so the mask
         texture's RGB is (1,1,1) on ink and its coverage lives in the ALPHA
         channel (vfx-text-cursor.html:597-620; readMask returns `.r` which is
         1.0 on ink). We sample the composite PNG's `.a` as that coverage.
         (`.r` here is the COLOUR channel, non-constant over the gradient
         shards, so using it would under-read coverage on the bright/dark
         gradient fills — measured 23.5% of ink has R<200.) */
      const mask = colormask.eval([lx * u.w, (1.0 - ly) * u.h]).a;
      const logo = image.eval([lx * u.w, (1.0 - ly) * u.h]);
      const ax = (gx - 0.5) * (u.w / u.h);
      const ay = gy - 0.5;
      const progress = u.progress;
      const mpx = (progress * 2.0 - 1.0) * (u.w / u.h);
      const mpy = 0.0;
      const dax = (mpx - ax) / 112.0;
      const day = (mpy - ay) / 112.0;
      var acc = 0.0;
      var rx = ax;
      var ry = ay;
      for (let i = 0.0; i < 112.0; i++) {
        rx += dax;
        ry += day;
        const h1 = fract(sin((rx * 489.0 + ry * 589.0 + i * 58.0)) * 492.0) * 2.0 - 1.0;
        const h2 = fract(sin((rx * 489.0 + (ry + 1.0) * 589.0 + (i + 1.0) * 58.0)) * 492.0) * 2.0 - 1.0;
        rx += h1 * 0.5 / 112.0;
        ry += h2 * 0.5 / 112.0;
        const bx = rx / (u.w / u.h) * 0.5 + 0.5;
        const by = ry * 0.5 + 0.5;
        const rlx = (bx - 0.5) / scale + 0.5;
        const rly = (by - 0.5) / scale + 0.5 + u.logoY / u.h;
        acc += colormask.eval([rlx * u.w, (1.0 - rly) * u.h]).a / 112.0;
      }
      var cr = cos((cos(acc * 4.9) - 0.0) * 0.6 * 3.141593) * acc * 3.65 - acc * 0.24;
      var cg = cos((cos(acc * 4.9) - 0.5) * 1.0 * 3.141593) * acc * 3.65 - acc * 0.24;
      var cb = cos((cos(acc * 4.9) - 1.0) * 0.5 * 3.141593) * acc * 3.65 - acc * 0.24;
      cr = max(cr - 0.035, 0.0) * 1.16;
      cg = max(cg - 0.035, 0.0) * 1.16;
      cb = max(cb - 0.035, 0.0) * 1.16;
      const sweep = exp(-pow((gx - progress) * 6.2, 2.0));
      const textProx = smoothstep(0.006, 0.34, acc);
      const longRay = smoothstep(0.004, 0.18, acc);
      const sx = progress * 1.8;
      const swR = 0.14 + cos((sx - 0.0) * 0.6 * 3.141593) * 0.28;
      const swG = 0.65 + cos((sx - 0.5) * 1.0 * 3.141593) * 0.28;
      const swB = 0.85 + cos((sx - 1.0) * 0.5 * 3.141593) * 0.28;
      const lrR = cos((progress + acc * 2.0 - 0.0) * 0.6 * 3.141593);
      const lrG = cos((progress + acc * 2.0 - 0.5) * 1.0 * 3.141593);
      const lrB = cos((progress + acc * 2.0 - 1.0) * 0.5 * 3.141593);
      const sweepTerm = sweep * (0.34 + textProx * 2.35);
      cr += swR * sweepTerm + lrR * longRay * 0.58;
      cg += swG * sweepTerm + lrG * longRay * 0.58;
      cb += swB * sweepTerm + lrB * longRay * 0.58;
      const logoTerm = acc * 1.18 + sweep * mask * 0.92;
      cr += logo.r * logoTerm;
      cg += logo.g * logoTerm;
      cb += logo.b * logoTerm;
      const mixv = u.mix;
      cr *= mixv; cg *= mixv; cb *= mixv;
      const lm = smoothstep(0.02, 0.75, logo.a);
      cr = mix(cr, logo.r, lm);
      cg = mix(cg, logo.g, lm);
      cb = mix(cb, logo.b, lm);
      const white = smoothstep(0.04, 0.38, mask) * 0.12 * mixv;
      return [clamp(cr + white, 0.0, 1.0), clamp(cg + white, 0.0, 1.0),
              clamp(cb + white, 0.0, 1.0), 1.0];
    };
    var stingEffect = ly.pixel(STING, {
      uniforms: { w: 'float', h: 'float', scale: 'float',
                  logoY: 'float', mix: 'float', progress: 'float' },
      backend: 'sksl'
    });
    var stingCanvas = ctx.getCanvasById('r1-sting-canvas');
    var stingChild = stingCanvas.getSubTree().makeShader(CK.TileMode.Clamp, CK.TileMode.Clamp);

    /* V1 state follows the source timeline: logoY 760→0 (power4.out, 1.0 s),
       effectMix 0→1 (power3.out, 0.34 s at 0.72), progress 0→1 (none, 2.28 s
       at 0.72), logoScale→0.4 (expo.in, 0.2 s at 2.9). */


    /* ── Scene r1 helpers (VFX sub-composition; ct 0 locally, no shift) ── */
var s1 = Math.max(0, ctx.currentTime);
    var effectMix = s1 <= 0.72 ? 0 : (s1 >= 1.06 ? 1 : 1 - Math.pow(1 - (s1 - 0.72) / 0.34, 3));
    var progress = s1 <= 0.72 ? 0 : (s1 >= 3.0 ? 1 : (s1 - 0.72) / 2.28);
    var logoScale = s1 < 2.9 ? 1 : (s1 >= 3.1 ? 0.4 : 1 - 0.6 * (s1 - 2.9) / 0.2);
    var logoT = s1 >= 1.0 ? 1 : 1 - Math.pow(1 - s1, 4);
    var logoY = 760 * (1 - logoT);
    (function paintSting() {
      if (s1 > 3.12) return;   // V1 is fully faded out by 3.1 s; skip the march
      var p = new CK.Paint();
      p.setShader(stingEffect.sample(
        [1920.0, 1080.0, logoScale, logoY, effectMix, progress],
        [stingChild, stingChild]));
      stingCanvas.drawRect(CK.XYWHRect(0, 0, 1920, 1080), p);
    })();

    /* ---- V2/V3 DOM refs ---- */
    var phraseA = ctx.getNode('r1-phrase-a');
    var phraseB = ctx.getNode('r1-phrase-b');
    var nextCard = ctx.getNode('r1-next-card');
    var nextBg = ctx.getNode('r1-next-bg');

    /* addTextCardSequence — 1:1 from source (typeStep .085, titleHold .25) */
    var HTML_TEXT = "HTML";
    var typeStep = 0.085, titleHold = 0.25;
    var htmlStart = 3.15;
    var typeEnd = htmlStart + (HTML_TEXT.length - 1) * typeStep;   // 3.405
    var slideStart = typeEnd + titleHold;                          // 3.655
    var slideEnd = slideStart + 0.05;                              // 3.705

    /* The source places the "HTML" word at the card centre at scale 1.8 (live
       getBoundingClientRect offset) and slides it home. For the typed-HTML
       look, type each glyph by revealing splitText parts (no textContent
       mutation exists) and slide the whole #html-word from +HTML_SLIDE_X. */
    var parts = ctx.splitText('r1-html-type', { type: 'chars' });
    T.set('r1-html-type', { opacity: 1 }, 0);
    T.set('r1-html-word', { x: 300, y: -6, scale: 1.8, transformOrigin: '50% 50%' }, 0);
    for (var i = 0; i < parts.length; i++) {
      T.set(parts[i], { opacity: 0 }, 0);
      T.set(parts[i], { opacity: 1 }, htmlStart + i * typeStep);
    }
    T.set('r1-html-caret', { opacity: 1 }, htmlStart - 0.05);
    T.set('r1-html-caret', { opacity: 0 }, typeEnd);
    T.to('r1-html-word', { x: 0, y: 0, scale: 1, duration: 0.05, ease: 'power2.out' }, slideStart);

    /* supporting words ("‑in", "canvas") enter, staggered 0.08 */
    T.set('r1-html-tail',   { opacity: 0, y: 54, scale: 0.96, filter: 'blur(10px)' }, 0);
    T.set('r1-canvas-word', { opacity: 0, y: 54, scale: 0.96, filter: 'blur(10px)' }, 0);
    T.to('r1-html-tail',   { opacity: 1, y: 0, scale: 1, filter: 'blur(0px)', duration: 0.42, ease: 'expo.out' }, slideEnd);
    T.to('r1-canvas-word', { opacity: 1, y: 0, scale: 1, filter: 'blur(0px)', duration: 0.42, ease: 'expo.out' }, slideEnd + 0.08);

    /* Source V1 beats: logoY 760→0 (power4.out 1.0 s); effectMix 0→1
       (power3.out 0.34 s) at 0.72; progress 0→1 (none 2.28 s) at 0.72;
       logoScale→0.4 (expo.in 0.2 s) at 2.9 with canvas opacity→0, blur 16. */
    T.set('r1-sting-canvas', { opacity: 1 }, 0);
    T.to('r1-sting-canvas', { filter: 'blur(16px)', duration: 0.2, ease: 'expo.in' }, 2.9);
    T.to('r1-sting-canvas', { opacity: 0, duration: 0.2, ease: 'expo.in' }, 2.9);

    /* ---- V2 card entry ---- */
    T.set('r1-next-bg', { opacity: 1 }, 3.1);
    T.set('r1-next-card', { opacity: 1, scale: 1.45, filter: 'blur(14px)', transformOrigin: '50% 50%' }, 3.1);
    T.to('r1-next-card', { scale: 0.88, filter: 'blur(0px)', duration: 0.9,
      /* source uses entryEase(t) = -0.806t²+1.806t (a fast ease-out, ~1% overshoot);
         a JS-function ease isn't supported, so use the closest preset power2.out. */
      ease: 'power2.out' }, 3.1);
    T.to('r1-next-card', { scale: 0.84, filter: 'blur(1.5px)', duration: 0.4, ease: 'linear' }, 4.0);

    /* ---- V2→V3 phrase swap ----
       phraseAReady = slideEnd + 0.42 + 0.08 = 4.205; phraseAExit = 4.705;
       phraseBStart = 5.065 */
    var phraseAExit = slideEnd + 0.42 + 0.08 + 0.5;   // 4.705
    var phraseBStart = phraseAExit + 0.36;            // 5.065
    T.to('r1-phrase-a', { x: -1480, filter: 'blur(8px)', duration: 0.36, ease: 'power2.in' }, phraseAExit);
    T.set('r1-phrase-a', { opacity: 0 }, phraseBStart);
    T.set('r1-phrase-b', { opacity: 1, x: 1480, filter: 'blur(8px)' }, phraseBStart);
    T.to('r1-phrase-b', { x: 0, filter: 'blur(0px)', duration: 0.48, ease: 'expo.out' }, phraseBStart);

    /* ---- V3→bridge (handoff to Act B), 5.85..6.35 ---- */
    T.to('r1-next-card', { y: -1180, filter: 'blur(24px)', duration: 0.5, ease: 'power2.in' }, 5.85);
    T.to('r1-next-bg', { opacity: 0, duration: 0.36, ease: 'power1.in' }, 5.99);
    T.to('r1-next-card', { opacity: 0, duration: 0.2, ease: 'power1.in' }, 6.15);
    }

    /* ── Scene r2 (HeyGen phone + prompt + send) ───────────────────────────
       Scene-local = abs − 6.033333. actB's local t acted as abs − 6.20, so
       scene-local = actB-local + 0.166667 (= 6.20 − 6.033333). */
    if (inWindow(1)) {

    /* local = source script time + OFFSET (HEYGEN_START 5.58 − 6.20) */
    var OFFSET = -0.62;   /* actB's own origin (6.20) — kept for the source-beat table below */

    /* ── phone: procedural 2D approximation of the Three.js GLB ────────
       Projected centre/size: projY(wy,depth) = 540 − wy·FOCAL/depth,
       FOCAL = 540/tan(17°) ≈ 1766.6; phone world height 3.2. */
    var FOCAL = 540.0 / Math.tan(17 * Math.PI / 180);
    function clamp01(v) { return v < 0 ? 0 : (v > 1 ? 1 : v); }
    function lerp(a, b, t) { return a + (b - a) * clamp01(t); }
    function pow2out(t) { return 1 - Math.pow(1 - clamp01(t), 2); }
    function pow3out(t) { return 1 - Math.pow(1 - clamp01(t), 3); }
    function pow3in(t)  { return Math.pow(clamp01(t), 3); }
    function expoOut(t) { t = clamp01(t); return t >= 1 ? 1 : 1 - Math.pow(2, -10 * t); }
    function power1out(t) { return clamp01(t); }
    var s2 = Math.max(0, ctx.currentTime);

    var phY, phRY, cZ, phRZ = 0.006;
    // S.phY −3.45→0.02 expo.out @0.08 source → local −0.54, dur 0.95
    phY = s2 < -0.3733333 ? -3.45 : lerp(-3.45, 0.02, expoOut((s2 + 0.3733333) / 0.95));
    // S.cZ 6.6→6.35 breatheEase @0.18 → local −0.44, dur 0.78
    cZ = s2 < -0.2733333 ? 6.6 : lerp(6.6, 6.35, pow3out((s2 + 0.2733333) / 0.78));
    // S.phRY PI−0.035 until spin @2.2 → local 1.58; PI→5PI over 1.73
    if (s2 < 1.7466667) phRY = Math.PI - 0.035;
    else if (s2 < 3.4766667) phRY = Math.PI - 0.035 + Math.PI * 4 * ((s2 - 1.7466667) / 1.73);
    else phRY = Math.PI * 5 - 0.035;
    // push-in @3.43 → local 2.81: phRZ→PI/2, cZ→3.85
    if (s2 >= 2.9766667) {
      var pk = pow3in((s2 - 2.9766667) / 0.85);
      phRZ = lerp(0.006, Math.PI / 2, pk);
      cZ = lerp(6.35, 3.85, pk);
    }
    var phoneH = 3.2 * FOCAL / cZ;
    var phoneW = phoneH * (390 / 844);
    var cy = 540 - phY * FOCAL / cZ;
    var phoneNode = ctx.getNode('r2-phone');
    // exit @4.04 → local 3.42: x→−1220 expo.out 0.53, opacity→0 0.18
    var exitX = s2 < 3.5866667 ? 0 : -1220 * expoOut((s2 - 3.5866667) / 0.53);
    phoneNode.left(960 + exitX - phoneW * 0.5);
    phoneNode.top(cy - phoneH * 0.5);
    phoneNode.width(phoneW);
    phoneNode.height(phoneH);
    var sx = Math.abs(Math.cos(phRY));         // flat body foreshortens on spin
    phoneNode.scaleX(sx < 0.05 ? 0.05 : sx);
    phoneNode.rotate(phRZ * 180 / Math.PI);
    var entryOp = pow2out((s2 + 0.3733333) / 0.5);
    var exitOp = s2 < 3.5866667 ? 1 : 1 - clamp01((s2 - 3.5866667) / 0.18);
    phoneNode.opacity(clamp01(entryOp) * exitOp);
    // S.scroll 0→0.9 power1.out @2.05 → local 1.43, dur 2.45; page scrolls
    var scroll = s2 < 1.5966667 ? 0 : 0.9 * power1out((s2 - 1.5966667) / 2.45);
    ctx.getNode('r2-phone-page').top(-scroll * 480);

    /* ── decl: bg video, finger, prompt, typing, send, copy ─────────── */

var T = ctx.timeline();
    // bg-video already faded in at abs 5.58 (before this act's 6.20 window)
    T.set('r2-bg-video', { opacity: 1 }, 0.1666666667);

    // finger: left 1260→805, top 1220→532 power3.out @0.30 dur 0.82
    T.set('r2-finger', { left: 1260, top: 1220, rotation: -75, opacity: 0 }, 0.1666666667);
    T.to('r2-finger', { opacity: 1, duration: 0.2, ease: 'power1.out' }, 0.2666666667);
    T.to('r2-finger', { left: 805, top: 532, duration: 0.82, ease: 'power3.out' }, 0.4666666667);
    // then top→−1900 power3.inOut @1.23 dur 0.68; opacity 0 @1.93
    T.to('r2-finger', { top: -1900, duration: 0.68, ease: 'power3.inOut' }, 1.396666667);
    T.set('r2-finger', { opacity: 0 }, 2.096666667);

    // prompt-scene @3.46: visible, x 620→0 blur→0 0.27 power2.out, opacity→1 0.48
    T.set('r2-prompt-scene', { opacity: 0, x: 620, filter: 'blur(18px)' }, 0.1666666667);
    T.to('r2-prompt-scene', { x: 0, filter: 'blur(0px)', duration: 0.27, ease: 'power2.out' }, 3.626666667);
    T.to('r2-prompt-scene', { opacity: 1, duration: 0.48, ease: 'power2.out' }, 3.626666667);
    T.set('r2-prompt-app', { x: 560, y: -120, scale: 3.15, transformOrigin: '50% 92%' }, 0.1666666667);
    // typing "npx hyperframes add iphone-canvas" @3.51 dur 0.9 — reveal glyphs
    var cp = ctx.splitText('r2-prompt-command', { type: 'chars' });
    for (var i = 0; i < cp.length; i++) {
      T.set(cp[i], { opacity: 0 }, 0);
      T.set(cp[i], { opacity: 1 }, 3.6766666667 + (i / cp.length) * 0.9);
    }
    T.set('r2-prompt-caret', { opacity: 1 }, 3.626666667);
    // caret stops typing @3.51+0.9=4.41
    // blink @6.25 → local 5.63 (repeat 3 yoyo steps)
    T.to('r2-prompt-caret', { opacity: 0, duration: 0.12, repeat: 3, yoyo: true, ease: 'steps(1)' }, 5.796666667);
    T.set('r2-prompt-caret', { opacity: 0 }, 4.576666667);
    // camera pan x→−1260 @3.51 dur 1.78 power1.in (accelerating)
    T.to('r2-prompt-app', { x: -1260, duration: 1.78, ease: 'power1.in' }, 3.676666667);
    // meta opacity→1 @4.28 dur 0.18
    T.to('r2-prompt-meta', { opacity: 1, duration: 0.18, ease: 'power1.out' }, 4.446666667);
    // topbar + command + meta fade/blur/scale0.86 @4.97 dur 0.2 power3.inOut
    T.to('r2-prompt-topbar', { opacity: 0, filter: 'blur(16px)', scale: 0.86, duration: 0.2, ease: 'power3.inOut', transformOrigin: '50% 50%' }, 5.136666667);
    T.to('r2-prompt-command', { opacity: 0, filter: 'blur(16px)', duration: 0.2, ease: 'power3.inOut' }, 5.136666667);
    T.to('r2-prompt-meta', { opacity: 0, filter: 'blur(16px)', duration: 0.2, ease: 'power3.inOut' }, 5.136666667);
    // composer bg → transparent @4.97 dur 0.2
    T.to('r2-prompt-composer', { backgroundColor: 'rgba(255,255,255,0)', borderColor: 'rgba(229,224,209,0)', duration: 0.2, ease: 'power3.inOut' }, 5.136666667);
    // send: y→−95 @5.07 dur 0.22 power2.out; scale→3 0.22 power3.out
    T.set('r2-prompt-send', { x: 0, y: 0, scale: 1 }, 0.1666666667);
    T.to('r2-prompt-send', { y: -95, duration: 0.22, ease: 'power2.out' }, 5.236666667);
    T.to('r2-prompt-send', { scale: 3, duration: 0.22, ease: 'power3.out', transformOrigin: '50% 50%' }, 5.236666667);
    // cursor @5.18 x280 y210 op1 0.28 power3.out; @5.48 x26 y38 0.46 power3.inOut
    T.set('r2-click-cursor', { x: 500, y: 620, scale: 0.95, opacity: 0, rotation: -6 }, 0.1666666667);
    T.to('r2-click-cursor', { x: 280, y: 210, opacity: 1, duration: 0.28, ease: 'power3.out' }, 5.346666667);
    T.to('r2-click-cursor', { x: 26, y: 38, duration: 0.46, ease: 'power3.inOut' }, 5.646666667);
    // click: send 3→2.62 (0.08 power2.in) @5.88; →3.12 back.out(2.2) 0.16 @5.97
    T.to('r2-prompt-send', { scale: 2.62, duration: 0.08, ease: 'power2.in' }, 6.046666667);
    T.to('r2-click-cursor', { scale: 0.82, duration: 0.08, ease: 'power2.in' }, 6.046666667);
    T.to('r2-prompt-send', { scale: 3.12, duration: 0.16, ease: 'back.out(2.2)' }, 6.136666667);
    T.to('r2-click-cursor', { scale: 0.95, duration: 0.16, ease: 'back.out(2.2)' }, 6.136666667);
    // exit @6.06: send y→−260, cursor y→−165, blur 8, opacity 0 dur 0.28 power2.in
    T.to('r2-prompt-send', { y: -260, filter: 'blur(8px)', opacity: 0, duration: 0.28, ease: 'power2.in' }, 6.226666667);
    T.to('r2-click-cursor', { y: -165, filter: 'blur(8px)', opacity: 0, duration: 0.28, ease: 'power2.in' }, 6.226666667);
    // game-change @6.34: y 220→0 blur→0 0.46 expo.out; opacity→1 0.24 power1.out
