    C4_zSplit = C4_seg(s4, ROT, EXIT - ROT, C4_p2io, C4_zSplit, 1.05);
    C4_xSplit = C4_seg(s4, ROT, EXIT - ROT, C4_p2io, C4_xSplit, 0.46);
    C4_redRotY = C4_seg(s4, ROT, EXIT - ROT, C4_p2io, C4_redRotY, -1.42);
    C4_greenRotY = C4_seg(s4, ROT, EXIT - ROT, C4_p2io, C4_greenRotY, -1.22);
    C4_blueRotY = C4_seg(s4, ROT, EXIT - ROT, C4_p2io, C4_blueRotY, -1.02);
    /* exit @RGB_EXIT_START dur .31 power3.in: C4_depthX/C4_depthZ/C4_xSplit/C4_zSplit/
       C4_planeScale/bloom/C4_sceneAlpha */
    C4_depthX = C4_seg(s4, EXIT, 0.31, C4_p3in, C4_depthX, -2.2);
    C4_depthZ = C4_seg(s4, EXIT, 0.31, C4_p3in, C4_depthZ, -2.65);
    C4_xSplit = C4_seg(s4, EXIT, 0.31, C4_p3in, C4_xSplit, 0.48);
    C4_zSplit = C4_seg(s4, EXIT, 0.31, C4_p3in, C4_zSplit, 0.48);
    C4_planeScale = C4_seg(s4, EXIT, 0.31, C4_p3in, C4_planeScale, 0.3);
    C4_bloomStrength = C4_seg(s4, EXIT, 0.31, C4_p3in, C4_bloomStrength, 0.58);
    C4_sceneAlpha = C4_seg(s4, EXIT, 0.31, C4_p3in, C4_sceneAlpha, 0.76);
    C4_camZ = C4_seg(s4, EXIT, 0.31, C4_p2io, C4_camZ, 4.35);   /* source uses p2.in here */
    C4_lookX = C4_seg(s4, EXIT, 0.31, C4_p2io, C4_lookX, -0.16);
    /* final fade @EXIT+0.31 dur .11 p1.in: bloom→0, C4_sceneAlpha→0 */
    C4_bloomStrength = C4_seg(s4, EXIT + 0.31, 0.11, C4_p1in, C4_bloomStrength, 0);
    C4_sceneAlpha = C4_seg(s4, EXIT + 0.31, 0.11, C4_p1in, C4_sceneAlpha, 0);

    /* ── V9 chromatic planes: three additive channel planes over black.
       redPlane = C4_depthX−C4_xSplit, C4_depthZ+C4_zSplit, rotY C4_redRotY;
       green = C4_depthX, C4_depthZ; blue = C4_depthX+C4_xSplit, C4_depthZ−C4_zSplit
       (index.html:1071-1073). Projected with the source camera fov 40, z 5
       (index.html:1009), so the three planes split apart in screen space. */
    var chromCanvas = ctx.getCanvasById('c4-chromatic-canvas');
    var chromNode = ctx.getNode('c4-chromatic-canvas');
    /* Exact perspective ray/plane projection, 1:1 with the source
       (PerspectiveCamera fov 40, W/H, position C = C4_camX/C4_camY/C4_camZ looking at
       C4_lookX/C4_lookY,0; index.html:1009/1071-1088). For pixel rect-local uv the
       view direction is D = F + sx*tanH*aspect*R + sy*tanH*U with
       sx,sy in [-1,1], F = normalize(L-C), R = normalize(F x up),
       U = R x F, tanH = tan(fov/2). Each RGB plane sits at world center Pc
       with a Y-rotation theta (normal n = (sin0,0,cos0)); the ray-plane hit is
       hit = C + t*D with t = -dot(C-Pc, n)/dot(D, n). Plane-local coords
       lx = (hit-Pc).x*cos - (hit-Pc).z*sin, ly = (hit-Pc).y; the still sample
       is (0.5 + lx/planeW, 0.5 - ly/planeH), planeW = 3.0*aspect, planeH = 3.0.
       The source uses three AdditiveBlending channel materials; we accumulate
       them into one plane (single additive draw) with the source lum formula. */
    var CHROM = (uv, image, u) => {
      const sx = uv.x / u.w * 2.0 - 1.0;
      const sy = uv.y / u.h * 2.0 - 1.0;
      const Dx = u.fx + sx * u.rx + sy * u.ux;
      const Dy = u.fy + sx * u.ry + sy * u.uy;
      const Dz = u.fz + sx * u.rz + sy * u.uz;
      const a = u.alpha;
      /* red plane: Pc=(C4_depthX-C4_xSplit,0,C4_depthZ+C4_zSplit), theta=C4_redRotY */
      const tR = -(((u.cx - u.px0) * u.sn0 + (u.cz - u.pz0) * u.cs0)) /
                 (Dx * u.sn0 + Dz * u.cs0);
      const exR = (u.cx + tR * Dx) - u.px0;
      const eyR = (u.cy + tR * Dy) - u.py0;
      const ezR = (u.cz + tR * Dz) - u.pz0;
      const lxR = (exR * u.cs0 - ezR * u.sn0) / u.scale;
      const lyR = eyR / u.scale;
      const sR = image.eval([clamp(lxR / u.pw + 0.5, 0.0, 1.0) * u.w,
                             clamp(0.5 - lyR / u.ph, 0.0, 1.0) * u.h]);
      /* green plane: Pc=(C4_depthX,0,C4_depthZ), theta=C4_greenRotY */
      const tG = -(((u.cx - u.px1) * u.sn1 + (u.cz - u.pz1) * u.cs1)) /
                 (Dx * u.sn1 + Dz * u.cs1);
      const exG = (u.cx + tG * Dx) - u.px1;
      const eyG = (u.cy + tG * Dy) - u.py1;
      const ezG = (u.cz + tG * Dz) - u.pz1;
      const lxG = (exG * u.cs1 - ezG * u.sn1) / u.scale;
      const lyG = eyG / u.scale;
      const sG = image.eval([clamp(lxG / u.pw + 0.5, 0.0, 1.0) * u.w,
                             clamp(0.5 - lyG / u.ph, 0.0, 1.0) * u.h]);
      /* blue plane: Pc=(C4_depthX+C4_xSplit,0,C4_depthZ-C4_zSplit), theta=C4_blueRotY */
      const tB = -(((u.cx - u.px2) * u.sn2 + (u.cz - u.pz2) * u.cs2)) /
                 (Dx * u.sn2 + Dz * u.cs2);
      const exB = (u.cx + tB * Dx) - u.px2;
      const eyB = (u.cy + tB * Dy) - u.py2;
      const ezB = (u.cz + tB * Dz) - u.pz2;
      const lxB = (exB * u.cs2 - ezB * u.sn2) / u.scale;
      const lyB = eyB / u.scale;
      const sB = image.eval([clamp(lxB / u.pw + 0.5, 0.0, 1.0) * u.w,
                             clamp(0.5 - lyB / u.ph, 0.0, 1.0) * u.h]);
      const lumR = sR.r * 0.6 + max(sR.g, sR.b) * 0.4;
      const lumG = sG.g * 0.6 + max(sG.r, sG.b) * 0.4;
      const lumB = sB.b * 0.6 + max(sB.r, sB.g) * 0.4;
      return [sR.r * lumR * a, sG.g * lumG * a, sB.b * lumB * a, 1.0];
    };
    var chromEffect = ly.pixel(CHROM, {
      uniforms: { w: 'float', h: 'float', pw: 'float', ph: 'float',
                  scale: 'float', alpha: 'float', bloom: 'float',
                  cx: 'float', cy: 'float', cz: 'float',
                  fx: 'float', fy: 'float', fz: 'float',
                  rx: 'float', ry: 'float', rz: 'float',
                  ux: 'float', uy: 'float', uz: 'float',
                  px0: 'float', py0: 'float', pz0: 'float', cs0: 'float', sn0: 'float',
                  px1: 'float', py1: 'float', pz1: 'float', cs1: 'float', sn1: 'float',
                  px2: 'float', py2: 'float', pz2: 'float', cs2: 'float', sn2: 'float' },
      backend: 'sksl'
    });
    var chromChild = chromCanvas.getSubTree().makeShader(CK.TileMode.Clamp, CK.TileMode.Clamp);
    (function paintChromatic() {
      if (s4 < CH0 || s4 > EXIT + 0.42) { chromNode.opacity(0); return; }
      chromNode.opacity(1);
      /* camera basis for the source PerspectiveCamera(40, W/H) at C4_camX/C4_camY/C4_camZ
         looking at C4_lookX/C4_lookY,0: F = normalize(L-C), R = normalize(F x up),
         U = R x F. planeW/planeH = the source PlaneGeometry(3.0*aspect, 3.0). */
      var PW = 1920.0, PH = 1080.0, aspect = PW / PH;
      var planeW = 3.0 * aspect, planeH = 3.0;
      var tanH = Math.tan(40.0 * Math.PI / 180.0 / 2.0);
      /* View basis from the source camera constants via THREE
         PerspectiveCamera.lookAt semantics — forward = normalize(target−eye),
         right = normalize(cross(forward, up_world=(0,1,0))), up = cross(right,
         forward). The engine derives this (util_camera_basis →
         crates/opencat-core/src/geom.rs::camera_basis, unit-tested) so the ray
         basis is a deterministic function of the source, never a sign picked
         by which frame measures better. Returns flat [fx,fy,fz,rx,ry,rz,ux,uy,uz]. */
      var B = __util_camera_basis([C4_camX, C4_camY, C4_camZ], [C4_lookX, C4_lookY, 0.0]);
      var Fx = B[0], Fy = B[1], Fz = B[2];
      var Rx = B[3], Ry = B[4], Rz = B[5];
      var Ux = B[6], Uy = B[7], Uz = B[8];
      /* fold the half-angle FOV into the basis so the lambda ray is
         D = F + sx*(tanH*aspect*R) + sy*(tanH*U), sx/sy in [-1,1] */
      Rx *= tanH * aspect; Ry *= tanH * aspect; Rz *= tanH * aspect;
      Ux *= tanH; Uy *= tanH; Uz *= tanH;
      var c0 = [Math.cos(C4_redRotY), Math.sin(C4_redRotY)];
      var c1 = [Math.cos(C4_greenRotY), Math.sin(C4_greenRotY)];
      var c2 = [Math.cos(C4_blueRotY), Math.sin(C4_blueRotY)];
      /* per-plane world center (index.html:1071-1073): red C4_depthX-C4_xSplit /
         C4_depthZ+C4_zSplit; green C4_depthX/C4_depthZ; blue C4_depthX+C4_xSplit / C4_depthZ-C4_zSplit. */
      var p = new CK.Paint();
      p.setShader(chromEffect.sample([
        PW, PH, planeW, planeH, C4_planeScale, C4_sceneAlpha, C4_bloomStrength,
        C4_camX, C4_camY, C4_camZ,
        Fx, Fy, Fz, Rx, Ry, Rz, Ux, Uy, Uz,
        C4_depthX - C4_xSplit, 0.0, C4_depthZ + C4_zSplit, c0[0], c0[1],
        C4_depthX,          0.0, C4_depthZ,          c1[0], c1[1],
        C4_depthX + C4_xSplit, 0.0, C4_depthZ - C4_zSplit, c2[0], c2[1]
      ], [chromChild]));
      /* composite the three additive channel planes */
      chromCanvas.drawRect(CK.XYWHRect(0, 0, 1920, 1080), p);
    })();
    }

    /* ── Scene r5 (CTA + portal reveal + end card) ───────────────────────
       Scene-local = abs − 16.8 → local = actC local − 3.467. */
    if (inWindow(4)) {
    var s5 = Math.max(0, ctx.currentTime);
    function C5_clamp01(v) { return v < 0 ? 0 : (v > 1 ? 1 : v); }
    function C5_p2out(t) { return 1 - Math.pow(1 - C5_clamp01(t), 2); }
    function C5_p1io(t)  { return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2; }
    function C5_p3in(t)  { return Math.pow(C5_clamp01(t), 3); }
    function C5_p3out(t) { return 1 - Math.pow(1 - C5_clamp01(t), 3); }
    function C5_seg(t, start, dur, ease, from, to) {
      if (t <= start) return from;
      return from + (to - from) * ease((t - start) / dur);
    }
    /* C5_* state defaults (index.html:914-941), scene-local as in r3/r4 */
    var C5_zSplit = 0, C5_xSplit = 0, C5_redRotY = 0, C5_greenRotY = 0, C5_blueRotY = 0;
    var C5_depthX = 0, C5_depthZ = 0, C5_planeScale = 1;
    var C5_camX = 0, C5_camY = 0, C5_camZ = 5, C5_lookX = 0, C5_lookY = 0;
    var C5_bloomStrength = 0.5, C5_sceneAlpha = 1;
    var C5_portalRadius = 0, C5_energyIntensity = 0, C5_chromaticStrength = 0;
    var C5_distortionStrength = 0, C5_edgeWidth = 0.06;
    var C5_PS = 11.44 - 7.66;                 // PORTAL_START, scene-local
    /* ── CTA entry + portal reveal (source index.html:1550-1585) ──────────
       Scene-local = abs − 16.8, so PORTAL_START 11.44 → local 3.687 in the
       source frame; here the r5 window already starts at the CTA hand-off,
       so the swap is retimed to the actC-derived origin kept in C5_PS.
       Numbers below are the source constants minus the r5 scene shift
       (RGB_EXIT_START 10.45 → local 2.697; 19.4 → 11.147; 20.35 → 12.097;
       20.85 → 12.597), never fitted. */
    var C5_EXIT = 10.45 - 7.753;
    var T = ctx.timeline();
    T.set('r5-upgrade-cta', { y: 240, opacity: 0, filter: 'blur(12px)' }, 0);
    T.to('r5-upgrade-cta', { y: 0, filter: 'blur(0px)', duration: 0.38, ease: 'expo.out' }, C5_EXIT - 2.387);
    T.to('r5-upgrade-cta', { opacity: 1, duration: 0.2, ease: 'power1.out' }, C5_EXIT - 2.387);
    T.set('r5-upgrade-cta', { opacity: 0 }, C5_PS);
    T.set('r5-portal-logo-frame', { opacity: 1 }, C5_PS);
    T.set('r5-portal-canvas', { opacity: 1 }, C5_PS);
    C5_energyIntensity = C5_seg(s5, C5_PS, 0.28, C5_p3out, 0, 1.0);
    C5_chromaticStrength = C5_seg(s5, C5_PS, 0.28, C5_p3out, 0, 0.04);
    C5_distortionStrength = C5_seg(s5, C5_PS, 0.28, C5_p3out, 0, 0.06);
    C5_edgeWidth = C5_seg(s5, C5_PS, 0.28, C5_p3out, 0.06, 0.08);
    C5_portalRadius = C5_seg(s5, C5_PS + 0.05, 7.59, C5_p1io, 0, 0.72);
    C5_portalRadius = C5_seg(s5, 19.4 - 7.66, 1.45, C5_p3in, C5_portalRadius, 1.8);
    var energy = C5_seg(s5, 20.35 - 7.66, 0.55, C5_p2out, 1.0, 0.0);
    T.set('r5-portal-canvas', { opacity: 0 }, 20.85 - 7.66);
    /* ── portal disc lambda (source index.html:1167-1213) ────────────────
       Outside the disc the canvas shows the CTA front texture `tFront`
       (mask = smoothstep(portalEdge-0.008, +0.008, dist)); inside the disc
       transparent (the white #portal-logo-frame below shows through). A
       glowing ring (source ring palette glows) rides the growing edge. */
    var PORTAL = (uv, image, u) => {
      const px = (uv.x / u.w - 0.5) * (u.w / u.h);
      const py = uv.y / u.h - 0.5;
      const dist = length([px, py]);
      const edgeDist = abs(dist - u.edge);
      const front = image.eval(uv);
      const mask = smoothstep(u.edge - 0.008, u.edge + 0.008, dist);
      const glowInner = smoothstep(u.ew, 0.0, edgeDist);
      const glowOuter = smoothstep(u.ew * 2.5, u.ew * 0.5, edgeDist);
      const glow = glowInner * glowOuter * u.energy;
      const ang = atan2(py, px);
      const phase = fract(ang / 6.2832 + u.time * 0.4);
      const ringR = mix(0.486, 0.290, sin(phase * 6.2832) * 0.5 + 0.5);
      const ringG = mix(0.227, 0.565, sin(phase * 6.2832) * 0.5 + 0.5);
      const ringB = mix(0.929, 1.000, sin(phase * 6.2832) * 0.5 + 0.5);
      const fr = front.r * mask + ringR * glow * 2.5;
      const fg = front.g * mask + ringG * glow * 2.5;
      const fb = front.b * mask + ringB * glow * 2.5;
      return [fr, fg, fb, clamp(mask + glow * 0.5, 0.0, 1.0)];
    };
    var portalEffect = ly.pixel(PORTAL, {
      uniforms: { w: 'float', h: 'float', edge: 'float', energy: 'float',
                  time: 'float', ew: 'float' },
      backend: 'sksl'
    });
    var portalCanvas = ctx.getCanvasById('r5-portal-canvas');
    var portalChild = portalCanvas.getSubTree().makeShader(CK.TileMode.Clamp, CK.TileMode.Clamp);
    (function paintPortal() {
      if (s5 < C5_PS) return;
      var p = new CK.Paint();
      p.setShader(portalEffect.sample(
        [1920.0, 1080.0, C5_portalRadius, C5_energy, s5, C5_edgeWidth], [portalChild]));
      portalCanvas.drawRect(CK.XYWHRect(0, 0, 1920, 1080), p);
    })();
    }
